import 'dart:io';
import 'dart:typed_data';

import 'package:plume_imap/src/discovery/dns.dart';
import 'package:test/test.dart';

import 'fake_dns_server.dart';

void main() {
  group('resolv.conf', () {
    late Directory dir;
    setUp(() async => dir = await Directory.systemTemp.createTemp('plume_dns'));
    tearDown(() => dir.delete(recursive: true));

    test('reads nameservers in order, skipping what it cannot use', () async {
      final file = File('${dir.path}/resolv.conf')
        ..writeAsStringSync('''
# Generated by NetworkManager
search lan
nameserver 127.0.0.53
; comment
nameserver   ::1
nameserver fe80::1%wlan0
nameserver not-an-ip
options edns0 trust-ad
nameserver 192.168.1.1
''');
      final servers = await DnsClient.readNameservers(file.path);
      expect(servers.map((a) => a.address), ['127.0.0.53', '::1', 'fe80::1%wlan0', '192.168.1.1']);
    });

    test('falls back to the local resolver', () async {
      expect(await DnsClient.readNameservers('${dir.path}/missing'), [InternetAddress.loopbackIPv4]);
      final empty = File('${dir.path}/empty')..writeAsStringSync('search lan\n');
      expect(await DnsClient.readNameservers(empty.path), [InternetAddress.loopbackIPv4]);
    });
  });

  group('MX over UDP', () {
    late FakeDnsServer server;
    setUp(() async => server = await FakeDnsServer.start());
    tearDown(() => server.close());

    DnsClient client({Duration timeout = const Duration(seconds: 2), List<InternetAddress>? servers}) =>
        DnsClient(nameservers: servers ?? [server.address], port: server.port, timeout: timeout);

    test('sorted by preference, compressed names expanded, CNAMEs skipped', () async {
      server.udp = (q) => [
        dnsResponse(
          q,
          cname: 'example.org',
          mx: [(20, 'alt.mx.example.net'), (10, 'mx1.example.org'), (30, 'MX3.Example.Org')],
        ),
      ];
      final records = await client().lookupMx('example.org');
      expect(records, const [
        MxRecord(10, 'mx1.example.org'),
        MxRecord(20, 'alt.mx.example.net'),
        MxRecord(30, 'mx3.example.org'),
      ]);
      expect(server.udpQueries.single.name, 'example.org');
    });

    test('ignores answers with the wrong ID or question', () async {
      server.udp = (q) => [
        dnsResponse(q, id: (q.id + 1) & 0xFFFF, mx: [(1, 'spoofed.example.com')]),
        dnsResponse(q, questionName: 'other.org', mx: [(1, 'spoofed.example.com')]),
        dnsResponse(q, mx: [(10, 'mx.example.org')]),
      ];
      expect(await client().lookupMx('example.org'), const [MxRecord(10, 'mx.example.org')]);
    });

    test('no such domain', () async {
      server.udp = (q) => [dnsResponse(q, rcode: 3)];
      expect(await client().lookupMx('nope.example'), isEmpty);
    });

    test('a null MX means no mail', () async {
      server.udp = (q) => [
        dnsResponse(q, mx: [(0, '')]),
      ];
      expect(await client().lookupMx('example.org'), isEmpty);
    });

    test('a silent server times out', () async {
      server.udp = (_) => [];
      final watch = Stopwatch()..start();
      expect(await client(timeout: const Duration(milliseconds: 200)).lookupMx('example.org'), isEmpty);
      expect(watch.elapsed, lessThan(const Duration(seconds: 2)));
    });

    test('truncated answers are retried over TCP', () async {
      server
        ..udp = ((q) => [dnsResponse(q, truncated: true)])
        ..tcp = ((q) => [
          dnsResponse(q, mx: [(5, 'big.example.org')]),
        ]);
      expect(await client().lookupMx('example.org'), const [MxRecord(5, 'big.example.org')]);
      expect(server.tcpQueries, hasLength(1));
    });

    test('a failing server is skipped for the next one', () async {
      // Linux routes all of 127/8 to loopback, so a second server can share
      // the port on another address.
      final second = await FakeDnsServer.start(address: '127.0.0.2', port: server.port);
      addTearDown(second.close);
      server.udp = (q) => [dnsResponse(q, rcode: 2)]; // SERVFAIL
      second.udp = (q) => [
        dnsResponse(q, mx: [(10, 'mx.example.org')]),
      ];
      final records = await client(servers: [server.address, second.address]).lookupMx('example.org');
      expect(records, const [MxRecord(10, 'mx.example.org')]);
      expect(second.udpQueries, hasLength(1));
    }, testOn: 'linux');

    test('invalid names are not sent', () async {
      expect(await client().lookupMx('bad..example'), isEmpty);
      expect(server.udpQueries, isEmpty);
    });
  });

  group('parsing', () {
    final query = encodeMxQuery(0x1234, 'example.org');

    test('rejects malformed and hostile responses', () {
      expect(DnsResponse.tryParse(Uint8List(5), id: 0x1234, question: query), isNull);
      // A compression pointer pointing at itself.
      final loop = Uint8List.fromList([
        0x12, 0x34, 0x81, 0x80, 0, 1, 0, 1, 0, 0, 0, 0, //
        ...encodeName('example.org'), 0, 15, 0, 1,
        0xC0, 12, 0, 15, 0, 1, 0, 0, 1, 44, 0, 4, 0, 10, 0xC0, 43,
      ]);
      expect(DnsResponse.tryParse(loop, id: 0x1234, question: query), isNull);
      // Answer length running past the end.
      final short = Uint8List.fromList([
        0x12, 0x34, 0x81, 0x80, 0, 1, 0, 1, 0, 0, 0, 0, //
        ...encodeName('example.org'), 0, 15, 0, 1,
        0xC0, 12, 0, 15, 0, 1, 0, 0, 1, 44, 0, 40, 0, 10,
      ]);
      expect(DnsResponse.tryParse(short, id: 0x1234, question: query), isNull);
      // A query, not a response.
      expect(DnsResponse.tryParse(query, id: 0x1234, question: query), isNull);
    });

    test('encodes queries', () {
      expect(query.sublist(0, 4), [0x12, 0x34, 0x01, 0x00]);
      expect(encodeName('a.bc'), [1, 97, 2, 98, 99, 0]);
      expect(encodeName('a.bc.'), [1, 97, 2, 98, 99, 0]);
      expect(() => encodeName('bad..name'), throwsArgumentError);
      expect(() => encodeName('bücher.de'), throwsArgumentError);
      expect(() => encodeName('${'x' * 64}.com'), throwsArgumentError);
    });
  });
}
